    36  IgmpType IgmpLayer::getType() const
    37  {
    38          uint8_t type = getIgmpHeader()->type;
    39          if (type < (uint8_t)IgmpType_MembershipQuery ||
    40                          (type > (uint8_t)IgmpType_LeaveGroup && type < (uint8_t)IgmpType_MulticastTracerouteResponse) ||
    41                          (type > (uint8_t)IgmpType_MulticastTraceroute && type < (uint8_t)IgmpType_MembershipReportV3) ||
    42                          (type > (uint8_t)IgmpType_MembershipReportV3 && type < (uint8_t)IgmpType_MulticastRouterAdvertisement) ||
    43                          type > IgmpType_MulticastRouterTermination)
    44                  return IgmpType_Unknown;
    45
    46          return (IgmpType)type;
    47  }
