    58  ProtocolType IgmpLayer::getIGMPVerFromData(uint8_t* data, size_t dataLen, bool& isQuery)
    59  {
    60          isQuery = false;
    61
    62          if (dataLen < 8 || data == nullptr)
    63                  return UnknownProtocol;
    64
    65          switch ((int)data[0])
    66          {
    67          case IgmpType_MembershipReportV2:
    68          case IgmpType_LeaveGroup:
    69                  return IGMPv2;
    70          case IgmpType_MembershipReportV1:
    71                  return IGMPv1;
    72          case IgmpType_MembershipReportV3:
    73                  return IGMPv3;
    74          case IgmpType_MembershipQuery:
    75          {
    76                  isQuery = true;
    77
    78                  if (dataLen >= sizeof(igmpv3_query_header))
    79                          return IGMPv3;
    80
    81                  if (data[1] == 0)
    82                          return IGMPv1;
    83                  else
    84                          return IGMPv2;
    85          }
    86          default:
    87                  return UnknownProtocol;
    88          }
    89  }
