    91  uint16_t IgmpLayer::calculateChecksum()
    92  {
    93          ScalarBuffer<uint16_t> buffer;
    94          buffer.buffer = (uint16_t*)getIgmpHeader();
    95          buffer.len = getHeaderLen();
    96          return computeChecksum(&buffer, 1);
    97  }
