    99  size_t IgmpLayer::getHeaderSizeByVerAndType(ProtocolType igmpVer, IgmpType igmpType) const
   100  {
   101          if (igmpVer == IGMPv1 || igmpVer == IGMPv2)
   102                  return sizeof(igmp_header);
   103
   104          if (igmpVer == IGMPv3)
   105          {
   106                  if (igmpType == IgmpType_MembershipQuery)
   107                          return sizeof(igmpv3_query_header);
   108                  else if (igmpType == IgmpType_MembershipReportV3)
   109                          return sizeof(igmpv3_report_header);
   110          }
